    "timeComplexity": "O(N)",
    "spaceComplexity": "O(1)",
    "functionName": "robHouses915",
    "starterCodeJS": "/**\n * @param {number[]} nums\n * @return {number}\n */\nfunction robHouses915(nums) {\n  // Write your code here\n  \n}\n",
