    "spaceComplexity": "O(N)",
    "functionName": "generateSubsets969",
    "starterCodeJS": "/**\n * @param {number[]} nums\n * @return {number[][]}\n */\nfunction generateSubsets969(nums) {\n  // Write your code here\n  \n}\n",
